<section class="admin-page" id="reviews"><h2>Product reviews</h2>@forelse($reviewQueue as $r)<div class="editor-card" data-search-row><h3>{{ $r->product }} · {{ $r->rating }}/5</h3><p>{{ $r->customer }} · {{ $r->title }}</p><p>{{ $r->body }}</p><form method="POST" action="{{ url('/admin/reviews/'.$r->id) }}">@csrf<label>Status<select name="status" class="form-select">@foreach(['pending','approved','rejected'] as $s)<option @selected($r->status===$s)>{{ $s }}</option>@endforeach</select></label><label class="d-block my-3">Store reply<textarea class="form-control" name="reply">{{ $r->reply }}</textarea></label><button type="submit" class="btn btn-primary">Save moderation</button></form></div>@empty<p>No reviews yet.</p>@endforelse</section>
